const awin=(id:string)=>"https://www.awin1.com/pclick.php?p="+id+"&a=3123004&m=125816";
export const imouModels:ImouModel[]=rows.map(([id,slug,name,category,description,items])=>{
 const variants=items.map(([variantId,title,priceCents,image])=>({id:variantId,name:title,priceCents,image,affiliateUrl:awin(variantId)}));
 return {id,slug,name,category,description,variants,image:variants[0].image,minPriceCents:Math.min(...variants.map(v=>v.priceCents))};
});
export const imouVariantCount=imouModels.reduce((n,m)=>n+m.variants.length,0);
export function imouModelPath(model:ImouModel):string{return "/imou/"+model.slug+"/";}
export function findImouModelBySlug(slug:string):ImouModel|undefined{return imouModels.find(m=>m.slug===slug);}
export function euroImou(cents:number):string{return new Intl.NumberFormat("de-DE",{style:"currency",currency:"EUR"}).format(cents/100);}
function normalize(query:string):string{return query.normalize("NFKD").replace(/\p{M}/gu,"").toLocaleLowerCase("de-DE").replace(/\s+/g," ").trim();}
export function findImouModels(query="",category=""):ImouModel[]{
 const words=normalize(query).split(/\s+/).filter(Boolean);
 return imouModels.filter(m=>(!category||m.category===category)&&
  words.every(w=>normalize(m.name+" "+m.category+" "+m.variants.map(v=>v.name).join(" ")).includes(w)));
}
export function imouOfferRows(query:string,limit=24):Array<{aw_product_id:string;product_name:string;price_cents:number;image_url:string;affiliate_url:string}>{
 const words=normalize(query).split(/\s+/).filter(Boolean);
 if(!words.length)return [];
 const matches:ReturnType<typeof imouOfferRows>=[];
 for(const model of imouModels)for(const v of model.variants){
  if(words.every(w=>normalize(v.name).includes(w))){
   matches.push({aw_product_id:v.id,product_name:v.name,price_cents:v.priceCents,image_url:v.image,affiliate_url:v.affiliateUrl});
  }
 }
 return matches.sort((a,b)=>a.price_cents-b.price_cents||a.product_name.localeCompare(b.product_name,"de")).slice(0,Math.max(1,Math.min(24,limit)));
}
